import { LlmProviderCard } from "@/features/settings/cards/LlmProviderCard";
import { ShellSelectorCard } from "@/features/settings/cards/ShellSelectorCard";
import { KitChangeApprovalCard } from "@/features/settings/cards/KitChangeApprovalCard";
import { TunnelSettings } from "@/features/tunnel";
import { MetricsCollectionCard } from "@/features/settings/cards/MetricsCollectionCard";
import { IdleReaperCard } from "@/features/settings/cards/IdleReaperCard";
import { PerfRetentionCard } from "@/features/settings/cards/PerfRetentionCard";
import { StorageCard } from "@/features/settings/cards/StorageCard";
import { SandboxedConsolesCard } from "@/features/settings/cards/SandboxedConsolesCard";
import { SessionLogCard } from "@/features/settings/cards/SessionLogCard";
import { Stack } from "@/shared/ui/layout/Stack";
import { SettingsPageHeader, SettingsSubHeader as Sub } from "@/features/settings/pages/SettingsPageHeader";

export function PlannerPage() {
  return (
    <Stack gap={18} style={{ maxWidth: 820 }}>
      <SettingsPageHeader
        title="Planner"
        description="LLM planning providers, autopilot, the session shell, mobile tunnel, performance, and storage."
      />

      <Sub>Providers &amp; automation</Sub>
      <LlmProviderCard />

      <Sub>Design</Sub>
      <KitChangeApprovalCard />

      <Sub>Shell</Sub>
      <ShellSelectorCard />

      <Sub>Mobile tunnel</Sub>
      <TunnelSettings />

      <Sub>Performance &amp; memory</Sub>
      <MetricsCollectionCard />
      <IdleReaperCard />
      <PerfRetentionCard />

      <Sub>Storage &amp; logs</Sub>
      <SandboxedConsolesCard />
      <StorageCard />
      {/* The log INVENTORY, the raw VIEWER and the retention caps moved to Logs → Streams
          (the-logs-streams-tab). They are the logs; a settings page is where you configure a
          thing, not where you read it — and the same screen now shows which emitters have never
          fired at all, which this page could not. Moved, not copied. */}

      <Sub>Session drill-down</Sub>
      <SessionLogCard />
    </Stack>
  );
}
